/// <summary>
/// Phase 1 of the SO extraction pipeline: dialog, credit check, ItemId-bundled guide check
/// and reservation, then hands off to METSalesPickingListFulfillmentBatch (Phase 2).
/// </summary>
class METSalesPickingListReservationBatch extends METRunBaseBatchMultiThreadBase
{
    container                   salesOrderList;
    container                   csdSalesOrderList;
    str                         csdGuid;
    boolean                     continueFromStagingLane;
    InventLocationId            extractionInventLocationId;
    METSalesOrderExtractionId   extractionId;
    container                   processedSalesContainer;
    container                   shipmentIdList;
    utcdatetime                 csdOrderExtractDateTime;
    container                   lineTaskBundles;
    boolean                     useLineLevelThreading;
    boolean                     isRetryRun;
    boolean                     finalTaskOnlyRetry;
    METProcMetrics              procMetrics;

    DialogField                 dlgOrderCount;
    DialogField                 dlgExtractionId;


    #define.CurrentVersion(1)
    #localmacro.CurrentList
        salesOrderList,
        csdSalesOrderList,
        csdGuid,
        continueFromStagingLane,
        extractionInventLocationId,
        extractionId,
        processedSalesContainer,
        shipmentIdList,
        csdOrderExtractDateTime,
        lineTaskBundles,
        useLineLevelThreading,
        isRetryRun,
        finalTaskOnlyRetry
    #endmacro

}

